        if (hasMigration) {
            emit MigrationParamsSet(
                pool,
                migrationParams.lockDurationAfterMigration,
                migrationParams.bptPercentageToMigrate,
                migrationParams.migrationWeightProjectToken,
                migrationParams.migrationWeightReserveToken
